  SELECT v_workspace_id, 'CJP', v_actor_id
  WHERE NOT EXISTS (SELECT 1 FROM public.clients
    WHERE workspace_id = v_workspace_id AND name = 'CJP' AND deleted_at IS NULL);
  INSERT INTO public.clients (workspace_id, name, created_by)
  SELECT v_workspace_id, 'CSPL', v_actor_id
  WHERE NOT EXISTS (SELECT 1 FROM public.clients
    WHERE workspace_id = v_workspace_id AND name = 'CSPL' AND deleted_at IS NULL);
  INSERT INTO public.clients (workspace_id, name, created_by)
  SELECT v_workspace_id, 'DAS', v_actor_id
  WHERE NOT EXISTS (SELECT 1 FROM public.clients
    WHERE workspace_id = v_workspace_id AND name = 'DAS' AND deleted_at IS NULL);
  INSERT INTO public.clients (workspace_id, name, created_by)
  SELECT v_workspace_id, 'DBN', v_actor_id
