  -- source row 6 -- invoice number not in source; placeholder assigned; payment amount absent in source; taken as TOTAL
  SELECT id INTO v_client_id FROM public.clients
    WHERE workspace_id = v_workspace_id AND name = 'UUR' AND deleted_at IS NULL LIMIT 1;
  IF NOT EXISTS (SELECT 1 FROM public.invoices
      WHERE workspace_id = v_workspace_id AND invoice_number = 'OLD/2021/005' AND deleted_at IS NULL) THEN
    INSERT INTO public.invoices (
      workspace_id, client_id, project_id, invoice_number, status, currency,
      issue_date, title, subtotal, discount_amount, dpp_numerator, dpp_denominator,
      ppn_percent, pph_percent, retensi_percent, dpp_amount, ppn_amount,
