      custom_fields, created_by
    ) VALUES (
      v_workspace_id, v_client_id, v_project_id, 'OLD/2021/005', 'paid', 'IDR',
      '2021-09-03', 'FLOOR DRAIN', 4140000.00, 0, 1, 1,
